// P-UX-21: build-time content-hash of the number-engine file set. Writes
// src/lib/engineVersion.ts (ENGINE_VERSION), which buildSchoolContext folds into
// computeAdvisoryHash so engine-code changes invalidate stale advisory caches.
//
// Runs in `npm run prebuild` (npm auto-runs prebuild before build; Vercel runs `npm run
// build`). Plain Node CommonJS (no tsx/TS-import) for build robustness; package.json is
// "commonjs" so this .cjs is also importable by the pure test suite. The generated file is
// committed so local dev + the tsx suite resolve it without a build.
//
// CRITICAL: contents are LF-normalized before hashing so Windows-dev CRLF and Vercel Linux
// LF produce the SAME token (otherwise the cache would bust on every Vercel build).
const { readFileSync, writeFileSync } = require('node:fs')
const { createHash } = require('node:crypto')

// Single source of truth for the hashed file set. MUST stay identical to ENGINE_HASH_FILES
// in src/lib/buildSchoolContext.ts (a test asserts parity). Engine MATH only — prose/context
// (buildSchoolContext) stays covered by PROMPT_VERSION.
const ENGINE_FILES = [
  'src/lib/budgetEngine.ts',
  'src/lib/calculations.ts',
  'src/lib/customLines.ts',
  'src/lib/facilityFinancing.ts',
  'src/lib/startupFunding.ts',
  'src/lib/staffingDefaults.ts',
  'src/lib/preOpening.ts',
  'src/lib/gradeExpansion.ts',
  'src/lib/stateConfig.ts',
  'src/lib/healthThresholds.ts',
  'src/lib/scenarioEngine.ts',
]

/** Normalize CRLF/CR to LF so the token is OS-independent. */
function normalizeLF(s) {
  return s.replace(/\r\n/g, '\n').replace(/\r/g, '\n')
}

/** Deterministic token from [{name, content}] — sort by name, LF-normalize, sha256, 12 hex. */
function engineVersionFromContents(files) {
  const h = createHash('sha256')
  for (const f of [...files].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))) {
    h.update(f.name)
    h.update('\0')
    h.update(normalizeLF(f.content))
    h.update('\0')
  }
  return h.digest('hex').slice(0, 12)
}

function computeEngineVersion(root = '.') {
  const files = ENGINE_FILES.map((name) => ({ name, content: readFileSync(`${root}/${name}`, 'utf8') }))
  return engineVersionFromContents(files)
}

function generate() {
  const v = computeEngineVersion()
  const out =
    `// AUTO-GENERATED by scripts/gen-engine-version.cjs (npm prebuild). Do not edit by hand.\n` +
    `// P-UX-21: LF-normalized content-hash of the number-engine file set; folded into\n` +
    `// computeAdvisoryHash so engine changes invalidate stale advisory caches.\n` +
    `export const ENGINE_VERSION = '${v}'\n`
  writeFileSync('src/lib/engineVersion.ts', out)
  console.log('[gen-engine-version] ENGINE_VERSION =', v)
}

module.exports = { ENGINE_FILES, normalizeLF, engineVersionFromContents, computeEngineVersion }

// Generate only when invoked directly (not when imported by the test).
if (require.main === module) generate()
